func newRateImportRow() unsafe.Pointer { return unsafe.Pointer(new(rateimport.RateImportRow)) }

func newNRateImportRow(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]rateimport.RateImportRow, n)))
}

func ptrRateImportRow(p unsafe.Pointer, c int32) any {
	r := (*rateimport.RateImportRow)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RateImportBatchID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.RowNumber))
	case 5:
		return &r.Cells
	case 6:
		return &r.Rule
	case 7:
		return &r.LaneKey
	case 8:
		return &r.Error
	case 9:
		return &r.CreatedAt
	}
	return nil
}

func valueRateImportRow(p unsafe.Pointer, c int32) any {
	r := (*rateimport.RateImportRow)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RateImportBatchID)
	case 4:
		return int64(r.RowNumber)
	case 5:
		if r.Cells == nil {
			return nil
		}
		return r.Cells
	case 6:
		if r.Rule == nil {
			return nil
		}
		return *r.Rule
	case 7:
		if r.LaneKey == "" {
			return nil
		}
		return r.LaneKey
	case 8:
		if r.Error == "" {
			return nil
		}
		return r.Error
	case 9:
		return r.CreatedAt
	}
	return nil
}

func attachRateImportRow(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*rateimport.RateImportRow)(p)
	switch rel {
	case 0:
		r.Batch = (*rateimport.RateImportBatch)(child)
	}
}

func init() {
	rateImportBatchesTable.Relations[0].Target = rateagreementdb.RateAgreementsSchema()
	rateImportBatchesTable.Relations[1].Target = RateImportRowsSchema()
	rateImportRowsTable.Relations[0].Target = RateImportBatchesSchema()
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumSourceFormat = [...]schema.EnumValue{
	{Value: `CSV`, Label: `CSV`},
	{Value: `XLSX`, Label: `XLSX`},
}

var enumStatus = [...]schema.EnumValue{
	{Value: `Pending`, Label: `Pending`, Doc: `StatusPending is uploaded but not yet read.`},
	{Value: `Parsed`, Label: `Parsed`, Doc: `StatusParsed means the rows were read and the dry run is ready to review.`},
	{Value: `Committed`, Label: `Committed`, Doc: `StatusCommitted means the sheet was applied to the agreement.`},
	{Value: `Failed`, Label: `Failed`, Doc: `StatusFailed means the sheet could not be read at all.`},
	{Value: `Discarded`, Label: `Discarded`, Doc: `StatusDiscarded means somebody read the dry run and said no.`},
}

